package main

import (
	"context"
	"log/slog"
	"os"
	"os/signal"
	"syscall"

	"github.com/anthropics/anthropic-sdk-go"
	"github.com/anthropics/anthropic-sdk-go/bedrock"
	"github.com/anthropics/anthropic-sdk-go/option"
	awsconfig "github.com/aws/aws-sdk-go-v2/config"
	"github.com/immuta/operations/services/televibe/internal/config"
	"github.com/immuta/operations/services/televibe/internal/evaluator"
	"github.com/immuta/operations/services/televibe/internal/watcher"
)

func main() {
	logger := slog.New(slog.NewJSONHandler(os.Stdout, nil))

	cfg, err := config.Load()
	if err != nil {
		logger.Error("configuration error", "error", err)
		os.Exit(1)
	}

	var anthropicClient anthropic.Client
	switch cfg.LLMProvider {
	case config.ProviderBedrock:
		opts := []func(*awsconfig.LoadOptions) error{}
		if cfg.BedrockRegion != "" {
			opts = append(opts, awsconfig.WithRegion(cfg.BedrockRegion))
		}
		anthropicClient = anthropic.NewClient(bedrock.WithLoadDefaultConfig(context.Background(), opts...))
		logger.Info("using AWS Bedrock", "region", cfg.BedrockRegion, "model", cfg.ClaudeModel)
	default:
		anthropicClient = anthropic.NewClient(option.WithAPIKey(cfg.AnthropicAPIKey))
		logger.Info("using Anthropic API", "model", cfg.ClaudeModel)
	}

	eval := evaluator.New(anthropicClient, cfg.ClaudeModel)

	ctx, cancel := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer cancel()

	w, err := watcher.New(ctx, cfg.TeleportAddr, cfg.TeleportIdentityFile, logger)
	if err != nil {
		logger.Error("failed to connect to teleport", "error", err)
		os.Exit(1)
	}
	defer w.Close()

	logger.Info("televibe started", "teleport_addr", cfg.TeleportAddr, "model", cfg.ClaudeModel)

	for {
		select {
		case req, ok := <-w.Requests():
			if !ok {
				return
			}
			go evaluate(ctx, eval, req, logger)
		case <-ctx.Done():
			return
		}
	}
}

func evaluate(ctx context.Context, eval *evaluator.Evaluator, req evaluator.Request, logger *slog.Logger) {
	a, err := eval.Evaluate(ctx, req)
	if err != nil {
		logger.Error("evaluation failed", "request_id", req.ID, "user", req.User, "error", err)
		return
	}

	logger.Info("access request evaluated",
		"request_id", req.ID,
		"user", req.User,
		"roles", req.Roles,
		"risk_score", a.RiskScore,
		"risk_level", a.RiskLevel,
		"has_jira_ticket", a.HasJIRATicket,
		"jira_ticket", a.JIRATicket,
		"description_quality", a.DescriptionQuality,
		"reasoning", a.Reasoning,
	)
}

package config

import (
	"errors"
	"os"
)

const (
	ProviderAnthropic = "anthropic"
	ProviderBedrock   = "bedrock"

	defaultModelAnthropic = "claude-sonnet-4-6"
	// Bedrock model IDs use cross-region inference profile format.
	// Override with CLAUDE_MODEL if you need a different version.
	defaultModelBedrock = "us.anthropic.claude-3-5-sonnet-20241022-v2:0"
)

type Config struct {
	TeleportAddr         string
	TeleportIdentityFile string
	LLMProvider          string // "anthropic" (default) or "bedrock"
	AnthropicAPIKey      string // required when LLMProvider == "anthropic"
	BedrockRegion        string // optional; falls back to AWS_DEFAULT_REGION / profile
	ClaudeModel          string
}

func Load() (*Config, error) {
	cfg := &Config{
		TeleportAddr:         os.Getenv("TELEPORT_ADDR"),
		TeleportIdentityFile: os.Getenv("TELEPORT_IDENTITY_FILE"),
		LLMProvider:          os.Getenv("LLM_PROVIDER"),
		AnthropicAPIKey:      os.Getenv("ANTHROPIC_API_KEY"),
		BedrockRegion:        os.Getenv("BEDROCK_REGION"),
		ClaudeModel:          os.Getenv("CLAUDE_MODEL"),
	}

	if cfg.LLMProvider == "" {
		cfg.LLMProvider = ProviderAnthropic
	}

	if cfg.ClaudeModel == "" {
		switch cfg.LLMProvider {
		case ProviderBedrock:
			cfg.ClaudeModel = defaultModelBedrock
		default:
			cfg.ClaudeModel = defaultModelAnthropic
		}
	}

	if cfg.TeleportAddr == "" {
		return nil, errors.New("TELEPORT_ADDR is required")
	}
	if cfg.TeleportIdentityFile == "" {
		return nil, errors.New("TELEPORT_IDENTITY_FILE is required")
	}

	switch cfg.LLMProvider {
	case ProviderAnthropic:
		if cfg.AnthropicAPIKey == "" {
			return nil, errors.New("ANTHROPIC_API_KEY is required when LLM_PROVIDER=anthropic")
		}
	case ProviderBedrock:
		// credentials come from the standard AWS credential chain
	default:
		return nil, errors.New("LLM_PROVIDER must be 'anthropic' or 'bedrock'")
	}

	return cfg, nil
}

package evaluator

import (
	"context"
	"encoding/json"
	"fmt"
	"regexp"
	"strings"

	"github.com/anthropics/anthropic-sdk-go"
)

// jiraPattern matches CUSTX-NNNN and ITSM-NNNN ticket references (case-insensitive).
var jiraPattern = regexp.MustCompile(`(?i)\b(CUSTX|ITSM)-\d+\b`)

// RiskLevel represents the severity of an access request.
type RiskLevel string

const (
	RiskLow    RiskLevel = "low"
	RiskMedium RiskLevel = "medium"
	RiskHigh   RiskLevel = "high"
)

// Assessment is the structured output of a Claude risk evaluation.
type Assessment struct {
	JIRATicket         string    `json:"jira_ticket"`
	HasJIRATicket      bool      `json:"has_jira_ticket"`
	DescriptionQuality string    `json:"description_quality"`
	RiskScore          int       `json:"risk_score"`
	RiskLevel          RiskLevel `json:"risk_level"`
	Reasoning          string    `json:"reasoning"`
}

// Request holds the access request fields that the evaluator needs.
type Request struct {
	ID     string
	User   string
	Roles  []string
	Reason string
}

// Evaluator calls Claude to assign a risk score to a Teleport access request.
type Evaluator struct {
	client anthropic.Client
	model  string
}

func New(client anthropic.Client, model string) *Evaluator {
	return &Evaluator{client: client, model: model}
}

func (e *Evaluator) Evaluate(ctx context.Context, req Request) (*Assessment, error) {
	tickets := jiraPattern.FindAllString(req.Reason, -1)
	prompt := buildPrompt(req.User, req.Roles, req.Reason, tickets)

	msg, err := e.client.Messages.New(ctx, anthropic.MessageNewParams{
		Model:     e.model,
		MaxTokens: 512,
		System: []anthropic.TextBlockParam{
			{Text: "You are a security risk evaluator for Teleport access requests. Respond only with valid JSON."},
		},
		Messages: []anthropic.MessageParam{
			anthropic.NewUserMessage(anthropic.NewTextBlock(prompt)),
		},
	})
	if err != nil {
		return nil, fmt.Errorf("claude API: %w", err)
	}

	if len(msg.Content) == 0 {
		return nil, fmt.Errorf("empty response from claude")
	}

	text := strings.TrimSpace(msg.Content[0].Text)
	// Strip markdown code fences that Claude sometimes adds.
	if strings.HasPrefix(text, "```") {
		if i := strings.Index(text[3:], "\n"); i >= 0 {
			text = strings.TrimSuffix(strings.TrimSpace(text[3+i+1:]), "```")
		}
	}

	var a Assessment
	if err := json.Unmarshal([]byte(text), &a); err != nil {
		return nil, fmt.Errorf("parsing response: %w (raw: %s)", err, text)
	}

	return &a, nil
}

func buildPrompt(user string, roles []string, reason string, tickets []string) string {
	ticketInfo := "none"
	if len(tickets) > 0 {
		ticketInfo = strings.Join(tickets, ", ")
	}

	return fmt.Sprintf(`You are a security risk evaluator for Teleport access requests. Respond ONLY with a valid JSON object — no explanation, no markdown.

Access request details:
  User:            %s
  Requested roles: %s
  Reason provided: %q
  JIRA tickets:    %s

Risk scoring rules:
  1–3  (low)    — valid JIRA ticket (CUSTX-NNN or ITSM-NNN) AND a clear description with business justification
  4–6  (medium) — either a valid JIRA ticket OR a clear description, but not both
  7–10 (high)   — no JIRA ticket AND no/vague description (single words or generic phrases like "need access" score 9–10)

Return exactly this JSON shape:
{
  "jira_ticket":          "<ticket ID or null>",
  "has_jira_ticket":      <true|false>,
  "description_quality":  "<none|poor|fair|good|excellent>",
  "risk_score":           <integer 1–10>,
  "risk_level":           "<low|medium|high>",
  "reasoning":            "<one concise sentence>"
}`,
		user,
		strings.Join(roles, ", "),
		reason,
		ticketInfo,
	)
}

