package watcher

import (
	"context"
	"fmt"
	"log/slog"
	"time"

	"github.com/gravitational/teleport/api/client"
	"github.com/gravitational/teleport/api/types"
	"github.com/immuta/operations/services/televibe/internal/evaluator"
)

const reconnectDelay = 5 * time.Second

// Watcher streams pending Teleport access requests onto a channel.
// It reconnects automatically on watcher failure.
type Watcher struct {
	client   *client.Client
	requests chan evaluator.Request
	logger   *slog.Logger
}

func New(ctx context.Context, addr, identityFile string, logger *slog.Logger) (*Watcher, error) {
	clt, err := client.New(ctx, client.Config{
		Addrs: []string{addr},
		Credentials: []client.Credentials{
			client.LoadIdentityFile(identityFile),
		},
	})
	if err != nil {
		return nil, fmt.Errorf("connecting to teleport: %w", err)
	}

	w := &Watcher{
		client:   clt,
		requests: make(chan evaluator.Request, 32),
		logger:   logger,
	}

	go w.watch(ctx)
	return w, nil
}

// Requests returns the channel of incoming pending access requests.
func (w *Watcher) Requests() <-chan evaluator.Request {
	return w.requests
}

// Close shuts down the Teleport client.
func (w *Watcher) Close() {
	w.client.Close()
}

func (w *Watcher) watch(ctx context.Context) {
	defer close(w.requests)

	for {
		if err := w.watchOnce(ctx); err != nil {
			if ctx.Err() != nil {
				return
			}
			w.logger.Error("watcher disconnected, reconnecting", "error", err, "delay", reconnectDelay)
			select {
			case <-time.After(reconnectDelay):
			case <-ctx.Done():
				return
			}
		}
	}
}

func (w *Watcher) watchOnce(ctx context.Context) error {
	watcher, err := w.client.NewWatcher(ctx, types.Watch{
		Kinds: []types.WatchKind{{Kind: types.KindAccessRequest}},
	})
	if err != nil {
		return fmt.Errorf("creating watcher: %w", err)
	}
	defer watcher.Close()

	// The first event must be OpInit confirming the watch is established.
	select {
	case event := <-watcher.Events():
		if event.Type != types.OpInit {
			return fmt.Errorf("expected OpInit, got %v", event.Type)
		}
		w.logger.Info("teleport watcher initialized")
	case <-watcher.Done():
		return fmt.Errorf("watcher closed during init: %w", watcher.Error())
	case <-ctx.Done():
		return ctx.Err()
	}

	for {
		select {
		case event := <-watcher.Events():
			if event.Type != types.OpPut {
				continue
			}
			req, ok := event.Resource.(types.AccessRequest)
			if !ok {
				continue
			}
			// Only forward newly-pending requests; ignore state transitions (approve/deny).
			if req.GetState() != types.RequestState_PENDING {
				continue
			}
			select {
			case w.requests <- toRequest(req):
			case <-ctx.Done():
				return ctx.Err()
			}
		case <-watcher.Done():
			return fmt.Errorf("watcher closed: %w", watcher.Error())
		case <-ctx.Done():
			return ctx.Err()
		}
	}
}

func toRequest(req types.AccessRequest) evaluator.Request {
	return evaluator.Request{
		ID:     req.GetName(),
		User:   req.GetUser(),
		Roles:  req.GetRoles(),
		Reason: req.GetRequestReason(),
	}
}

package config

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestLoad(t *testing.T) {
	allKeys := []string{
		"TELEPORT_ADDR", "TELEPORT_IDENTITY_FILE",
		"LLM_PROVIDER", "ANTHROPIC_API_KEY", "BEDROCK_REGION", "CLAUDE_MODEL",
	}

	base := map[string]string{
		"TELEPORT_ADDR":          "tp.example.com:443",
		"TELEPORT_IDENTITY_FILE": "/id.pem",
		"ANTHROPIC_API_KEY":      "sk-ant-key",
	}

	tests := []struct {
		name             string
		env              map[string]string
		wantErr          string
		wantProvider     string
		wantModel        string
		wantBedrockRegion string
	}{
		{
			name:    "missing TELEPORT_ADDR",
			env:     map[string]string{"TELEPORT_IDENTITY_FILE": "/id.pem", "ANTHROPIC_API_KEY": "key"},
			wantErr: "TELEPORT_ADDR is required",
		},
		{
			name:    "missing TELEPORT_IDENTITY_FILE",
			env:     map[string]string{"TELEPORT_ADDR": "tp.example.com:443", "ANTHROPIC_API_KEY": "key"},
			wantErr: "TELEPORT_IDENTITY_FILE is required",
		},
		{
			name:    "missing ANTHROPIC_API_KEY with default provider",
			env:     map[string]string{"TELEPORT_ADDR": "tp.example.com:443", "TELEPORT_IDENTITY_FILE": "/id.pem"},
			wantErr: "ANTHROPIC_API_KEY is required",
		},
		{
			name:    "invalid LLM_PROVIDER",
			env:     merge(base, map[string]string{"LLM_PROVIDER": "openai"}),
			wantErr: "LLM_PROVIDER must be",
		},
		{
			name:         "defaults (anthropic)",
			env:          base,
			wantProvider: ProviderAnthropic,
			wantModel:    defaultModelAnthropic,
		},
		{
			name:         "explicit anthropic provider",
			env:          merge(base, map[string]string{"LLM_PROVIDER": "anthropic"}),
			wantProvider: ProviderAnthropic,
			wantModel:    defaultModelAnthropic,
		},
		{
			name:         "bedrock provider, no API key required",
			env:          map[string]string{"TELEPORT_ADDR": "tp.example.com:443", "TELEPORT_IDENTITY_FILE": "/id.pem", "LLM_PROVIDER": "bedrock"},
			wantProvider: ProviderBedrock,
			wantModel:    defaultModelBedrock,
		},
		{
			name:              "bedrock provider with region",
			env:               map[string]string{"TELEPORT_ADDR": "tp.example.com:443", "TELEPORT_IDENTITY_FILE": "/id.pem", "LLM_PROVIDER": "bedrock", "BEDROCK_REGION": "eu-west-1"},
			wantProvider:      ProviderBedrock,
			wantModel:         defaultModelBedrock,
			wantBedrockRegion: "eu-west-1",
		},
		{
			name:         "custom model overrides provider default",
			env:          merge(base, map[string]string{"CLAUDE_MODEL": "claude-opus-4-7"}),
			wantProvider: ProviderAnthropic,
			wantModel:    "claude-opus-4-7",
		},
		{
			name:         "bedrock with custom model",
			env:          map[string]string{"TELEPORT_ADDR": "tp.example.com:443", "TELEPORT_IDENTITY_FILE": "/id.pem", "LLM_PROVIDER": "bedrock", "CLAUDE_MODEL": "us.anthropic.claude-3-7-sonnet-20250219-v1:0"},
			wantProvider: ProviderBedrock,
			wantModel:    "us.anthropic.claude-3-7-sonnet-20250219-v1:0",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			for _, key := range allKeys {
				t.Setenv(key, "")
			}
			for k, v := range tt.env {
				t.Setenv(k, v)
			}

			cfg, err := Load()

			if tt.wantErr != "" {
				require.Error(t, err)
				assert.Contains(t, err.Error(), tt.wantErr)
				return
			}

			require.NoError(t, err)
			assert.Equal(t, tt.wantProvider, cfg.LLMProvider)
			assert.Equal(t, tt.wantModel, cfg.ClaudeModel)
			assert.Equal(t, tt.wantBedrockRegion, cfg.BedrockRegion)
		})
	}
}

func merge(base, overrides map[string]string) map[string]string {
	out := make(map[string]string, len(base)+len(overrides))
	for k, v := range base {
		out[k] = v
	}
	for k, v := range overrides {
		out[k] = v
	}
	return out
}

package evaluator

import (
	"testing"

	"github.com/stretchr/testify/assert"
)

func TestBuildPrompt_JiraTickets(t *testing.T) {
	tests := []struct {
		name        string
		reason      string
		wantTickets []string
	}{
		{
			name:        "CUSTX ticket",
			reason:      "Working on CUSTX-1234 customer migration",
			wantTickets: []string{"CUSTX-1234"},
		},
		{
			name:        "ITSM ticket",
			reason:      "Resolving ITSM-9999 outage",
			wantTickets: []string{"ITSM-9999"},
		},
		{
			name:        "multiple tickets",
			reason:      "CUSTX-100 and ITSM-200 both require this",
			wantTickets: []string{"CUSTX-100", "ITSM-200"},
		},
		{
			name:        "case insensitive",
			reason:      "custx-555 access needed",
			wantTickets: []string{"custx-555"},
		},
		{
			name:        "no ticket",
			reason:      "I need access to the database",
			wantTickets: nil,
		},
		{
			name:        "unrelated pattern",
			reason:      "PROJ-123 is not a valid project",
			wantTickets: nil,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := jiraPattern.FindAllString(tt.reason, -1)
			assert.Equal(t, tt.wantTickets, got)
		})
	}
}

func TestBuildPrompt_ContainsRequiredFields(t *testing.T) {
	prompt := buildPrompt("alice", []string{"prod-db-readonly", "prod-k8s-viewer"}, "ITSM-42 emergency access needed", []string{"ITSM-42"})

	assert.Contains(t, prompt, "alice")
	assert.Contains(t, prompt, "prod-db-readonly")
	assert.Contains(t, prompt, "prod-k8s-viewer")
	assert.Contains(t, prompt, "ITSM-42")
	assert.Contains(t, prompt, "risk_score")
	assert.Contains(t, prompt, "reasoning")
}

