package config

import (
	"errors"
	"fmt"
	"os"
	"strconv"
)

const (
	ProviderAnthropic = "anthropic"
	ProviderBedrock   = "bedrock"

	defaultModelAnthropic = "claude-sonnet-4-6"
	// Bedrock model IDs use cross-region inference profile format.
	// Override with CLAUDE_MODEL if you need a different version.
	defaultModelBedrock = "us.anthropic.claude-3-5-sonnet-20241022-v2:0"

	defaultDeltaLow    = 1
	defaultDeltaMedium = 0
	defaultDeltaHigh   = -2
	defaultRepMin      = -20
	defaultRepMax      = 20
	defaultRepStart    = 0
)

// Reputation controls how assessments adjust per-user reputation scores.
type Reputation struct {
	DeltaLow    int // applied when the assessment is low risk
	DeltaMedium int // applied when the assessment is medium risk
	DeltaHigh   int // applied when the assessment is high risk
	Min         int // lower clamp
	Max         int // upper clamp
	Start       int // starting score for a user with no existing trait
}

type Config struct {
	TeleportAddr         string
	TeleportIdentityFile string
	LLMProvider          string // "anthropic" (default) or "bedrock"
	AnthropicAPIKey      string // required when LLMProvider == "anthropic"
	BedrockRegion        string // optional; falls back to AWS_DEFAULT_REGION / profile
	ClaudeModel          string
	OTLPEndpoint         string // OTEL_EXPORTER_OTLP_ENDPOINT; empty disables metric shipping
	Reputation           Reputation
}

func Load() (*Config, error) {
	cfg := &Config{
		TeleportAddr:         os.Getenv("TELEPORT_ADDR"),
		TeleportIdentityFile: os.Getenv("TELEPORT_IDENTITY_FILE"),
		LLMProvider:          os.Getenv("LLM_PROVIDER"),
		AnthropicAPIKey:      os.Getenv("ANTHROPIC_API_KEY"),
		BedrockRegion:        os.Getenv("BEDROCK_REGION"),
		ClaudeModel:          os.Getenv("CLAUDE_MODEL"),
		OTLPEndpoint:         os.Getenv("OTEL_EXPORTER_OTLP_ENDPOINT"),
	}

	if cfg.LLMProvider == "" {
		cfg.LLMProvider = ProviderAnthropic
	}

	if cfg.ClaudeModel == "" {
		switch cfg.LLMProvider {
		case ProviderBedrock:
			cfg.ClaudeModel = defaultModelBedrock
		default:
			cfg.ClaudeModel = defaultModelAnthropic
		}
	}

	rep, err := loadReputation()
	if err != nil {
		return nil, err
	}
	cfg.Reputation = rep

	if cfg.TeleportAddr == "" {
		return nil, errors.New("TELEPORT_ADDR is required")
	}
	if cfg.TeleportIdentityFile == "" {
		return nil, errors.New("TELEPORT_IDENTITY_FILE is required")
	}

	switch cfg.LLMProvider {
	case ProviderAnthropic:
		if cfg.AnthropicAPIKey == "" {
			return nil, errors.New("ANTHROPIC_API_KEY is required when LLM_PROVIDER=anthropic")
		}
	case ProviderBedrock:
		// credentials come from the standard AWS credential chain
	default:
		return nil, errors.New("LLM_PROVIDER must be 'anthropic' or 'bedrock'")
	}

	return cfg, nil
}

func loadReputation() (Reputation, error) {
	rep := Reputation{
		DeltaLow:    defaultDeltaLow,
		DeltaMedium: defaultDeltaMedium,
		DeltaHigh:   defaultDeltaHigh,
		Min:         defaultRepMin,
		Max:         defaultRepMax,
		Start:       defaultRepStart,
	}

	fields := []struct {
		env string
		dst *int
	}{
		{"REPUTATION_DELTA_LOW", &rep.DeltaLow},
		{"REPUTATION_DELTA_MEDIUM", &rep.DeltaMedium},
		{"REPUTATION_DELTA_HIGH", &rep.DeltaHigh},
		{"REPUTATION_MIN", &rep.Min},
		{"REPUTATION_MAX", &rep.Max},
		{"REPUTATION_START", &rep.Start},
	}

	for _, f := range fields {
		v := os.Getenv(f.env)
		if v == "" {
			continue
		}
		n, err := strconv.Atoi(v)
		if err != nil {
			return Reputation{}, fmt.Errorf("%s must be an integer: %w", f.env, err)
		}
		*f.dst = n
	}

	if rep.Min > rep.Max {
		return Reputation{}, fmt.Errorf("REPUTATION_MIN (%d) must be <= REPUTATION_MAX (%d)", rep.Min, rep.Max)
	}
	if rep.Start < rep.Min || rep.Start > rep.Max {
		return Reputation{}, fmt.Errorf("REPUTATION_START (%d) must be within [%d, %d]", rep.Start, rep.Min, rep.Max)
	}

	return rep, nil
}

