// Package reputation maintains a per-user reputation score in Teleport user
// traits based on evaluated access request risk. Scores are read and written
// as string traits so they surface to approvers in the Teleport UI.
package reputation

import (
	"context"
	"fmt"
	"strconv"
	"sync"
	"time"

	"github.com/gravitational/teleport/api/types"
	"github.com/immuta/operations/services/televibe/internal/config"
	"github.com/immuta/operations/services/televibe/internal/evaluator"
)

const (
	TraitScore     = "reputation_score"
	TraitUpdatedAt = "reputation_updated_at"
	TraitLastDelta = "reputation_last_delta"
)

// UserClient is the subset of the Teleport API the manager needs.
type UserClient interface {
	GetUser(ctx context.Context, name string, withSecrets bool) (types.User, error)
	UpdateUser(ctx context.Context, user types.User) (types.User, error)
}

// Update describes the result of applying an assessment to a user's score.
type Update struct {
	User     string
	Previous int
	Delta    int
	New      int
}

// Manager updates per-user reputation traits based on assessment outcomes.
type Manager struct {
	client UserClient
	cfg    config.Reputation
	now    func() time.Time

	mu    sync.Mutex
	locks map[string]*sync.Mutex
}

func New(client UserClient, cfg config.Reputation) *Manager {
	return &Manager{
		client: client,
		cfg:    cfg,
		now:    time.Now,
		locks:  make(map[string]*sync.Mutex),
	}
}

// Compute returns the new (clamped) score and the delta applied, given the
// previous score, the risk level of the assessment, and the reputation config.
// Exposed for unit tests and callers that want to preview the result.
func Compute(prev int, level evaluator.RiskLevel, cfg config.Reputation) (next, delta int) {
	switch level {
	case evaluator.RiskLow:
		delta = cfg.DeltaLow
	case evaluator.RiskHigh:
		delta = cfg.DeltaHigh
	default:
		delta = cfg.DeltaMedium
	}
	return clamp(prev+delta, cfg.Min, cfg.Max), delta
}

// Apply reads the user's current reputation, computes and writes the new
// score, and returns what changed. Concurrent Apply calls for the same user
// are serialized to avoid clobbering writes.
func (m *Manager) Apply(ctx context.Context, username string, a *evaluator.Assessment) (Update, error) {
	lock := m.userLock(username)
	lock.Lock()
	defer lock.Unlock()

	user, err := m.client.GetUser(ctx, username, false)
	if err != nil {
		return Update{}, fmt.Errorf("get user %q: %w", username, err)
	}

	traits := user.GetTraits()
	if traits == nil {
		traits = make(map[string][]string)
	}

	prev := m.cfg.Start
	if existing, ok := firstTrait(traits, TraitScore); ok {
		if n, err := strconv.Atoi(existing); err == nil {
			prev = clamp(n, m.cfg.Min, m.cfg.Max)
		}
	}

	next, delta := Compute(prev, a.RiskLevel, m.cfg)

	traits[TraitScore] = []string{strconv.Itoa(next)}
	traits[TraitUpdatedAt] = []string{m.now().UTC().Format(time.RFC3339)}
	traits[TraitLastDelta] = []string{strconv.Itoa(delta)}
	user.SetTraits(traits)

	if _, err := m.client.UpdateUser(ctx, user); err != nil {
		return Update{}, fmt.Errorf("update user %q: %w", username, err)
	}

	return Update{User: username, Previous: prev, Delta: delta, New: next}, nil
}

func (m *Manager) userLock(user string) *sync.Mutex {
	m.mu.Lock()
	defer m.mu.Unlock()
	l, ok := m.locks[user]
	if !ok {
		l = &sync.Mutex{}
		m.locks[user] = l
	}
	return l
}

func firstTrait(t map[string][]string, key string) (string, bool) {
	v, ok := t[key]
	if !ok || len(v) == 0 {
		return "", false
	}
	return v[0], true
}

func clamp(n, lo, hi int) int {
	if n < lo {
		return lo
	}
	if n > hi {
		return hi
	}
	return n
}

