	"time"

	"github.com/gravitational/teleport/api/types"
	"github.com/immuta/operations/services/televibe/internal/config"
	"github.com/immuta/operations/services/televibe/internal/evaluator"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func defaultCfg() config.Reputation {
	return config.Reputation{
		DeltaLow:    1,
		DeltaMedium: 0,
		DeltaHigh:   -2,
		Min:         -20,
		Max:         20,
		Start:       0,
	}
}

func TestCompute(t *testing.T) {
	cfg := defaultCfg()

	tests := []struct {
		name      string
		prev      int
		level     evaluator.RiskLevel
		wantNext  int
		wantDelta int
	}{
		{"low adds DeltaLow", 5, evaluator.RiskLow, 6, 1},
		{"medium no-op by default", 5, evaluator.RiskMedium, 5, 0},
		{"high subtracts", 5, evaluator.RiskHigh, 3, -2},
		{"clamp at max", 20, evaluator.RiskLow, 20, 1},
		{"clamp at min", -20, evaluator.RiskHigh, -20, -2},
		{"unknown level treated as medium", -3, evaluator.RiskLevel("weird"), -3, 0},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			next, delta := Compute(tt.prev, tt.level, cfg)
			assert.Equal(t, tt.wantNext, next, "next score")
			assert.Equal(t, tt.wantDelta, delta, "delta applied")
		})
	}
}

// fakeUserClient captures GetUser/UpdateUser calls against an in-memory map.
type fakeUserClient struct {
	mu      sync.Mutex
	users   map[string]types.User
	getErr  error
	putErr  error
	updates int
}

func newFakeUserClient(t *testing.T, existing map[string]map[string][]string) *fakeUserClient {
	t.Helper()
	f := &fakeUserClient{users: make(map[string]types.User)}
	for name, traits := range existing {
		u, err := types.NewUser(name)
		require.NoError(t, err)
		if traits != nil {
			u.SetTraits(traits)
		}
		f.users[name] = u
	}
	return f
}

func (f *fakeUserClient) GetUser(_ context.Context, name string, _ bool) (types.User, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.getErr != nil {
		return nil, f.getErr
	}
	u, ok := f.users[name]
	if !ok {
		return nil, errors.New("user not found")
	}
	return u, nil
}

func (f *fakeUserClient) UpdateUser(_ context.Context, u types.User) (types.User, error) {
	f.mu.Lock()
	defer f.mu.Unlock()
	if f.putErr != nil {
		return nil, f.putErr
	}
	f.users[u.GetName()] = u
	f.updates++
	return u, nil
}

func TestManager_Apply_NewUserStartsAtStart(t *testing.T) {
	cfg := defaultCfg()
	cfg.Start = 3

	client := newFakeUserClient(t, map[string]map[string][]string{"alice": nil})
	m := New(client, cfg)
	m.now = func() time.Time { return time.Date(2026, 4, 23, 12, 0, 0, 0, time.UTC) }

	got, err := m.Apply(context.Background(), "alice", &evaluator.Assessment{RiskLevel: evaluator.RiskHigh})
	require.NoError(t, err)

	assert.Equal(t, Update{User: "alice", Previous: 3, Delta: -2, New: 1}, got)

	traits := client.users["alice"].GetTraits()
	assert.Equal(t, []string{"1"}, traits[TraitScore])
	assert.Equal(t, []string{"-2"}, traits[TraitLastDelta])
	assert.Equal(t, []string{"2026-04-23T12:00:00Z"}, traits[TraitUpdatedAt])
}

func TestManager_Apply_ExistingScoreRead(t *testing.T) {
	cfg := defaultCfg()
	client := newFakeUserClient(t, map[string]map[string][]string{
		"bob": {TraitScore: {"-5"}},
	})
	m := New(client, cfg)

	got, err := m.Apply(context.Background(), "bob", &evaluator.Assessment{RiskLevel: evaluator.RiskLow})
	require.NoError(t, err)
	assert.Equal(t, -5, got.Previous)
	assert.Equal(t, 1, got.Delta)
	assert.Equal(t, -4, got.New)
}

func TestManager_Apply_CorruptedScoreResetsToStart(t *testing.T) {
	cfg := defaultCfg()
	cfg.Start = 7
	client := newFakeUserClient(t, map[string]map[string][]string{
		"carol": {TraitScore: {"not-a-number"}},
	})
	m := New(client, cfg)

	got, err := m.Apply(context.Background(), "carol", &evaluator.Assessment{RiskLevel: evaluator.RiskLow})
	require.NoError(t, err)
	assert.Equal(t, 7, got.Previous, "should fall back to Start when trait unparseable")
	assert.Equal(t, 8, got.New)
}

func TestManager_Apply_ClampsExistingOutOfRangeScore(t *testing.T) {
	cfg := defaultCfg() // [-20, 20]
	client := newFakeUserClient(t, map[string]map[string][]string{
		"dave": {TraitScore: {"9999"}},
	})
	m := New(client, cfg)

	got, err := m.Apply(context.Background(), "dave", &evaluator.Assessment{RiskLevel: evaluator.RiskHigh})
	require.NoError(t, err)
	assert.Equal(t, 20, got.Previous, "stored score outside range is clamped on read")
	assert.Equal(t, 18, got.New)
}

func TestManager_Apply_PropagatesGetError(t *testing.T) {
	client := newFakeUserClient(t, nil)
	client.getErr = errors.New("teleport down")
	m := New(client, defaultCfg())

	_, err := m.Apply(context.Background(), "eve", &evaluator.Assessment{RiskLevel: evaluator.RiskLow})
	require.Error(t, err)
	assert.Contains(t, err.Error(), "teleport down")
}

func TestManager_Apply_PropagatesUpdateError(t *testing.T) {
	client := newFakeUserClient(t, map[string]map[string][]string{"frank": nil})
	client.putErr = errors.New("write rejected")
	m := New(client, defaultCfg())

	_, err := m.Apply(context.Background(), "frank", &evaluator.Assessment{RiskLevel: evaluator.RiskLow})
	require.Error(t, err)
	assert.Contains(t, err.Error(), "write rejected")
}

// Concurrent Apply calls for the same user must not clobber each other:
// each call must see the effect of the previous one.
func TestManager_Apply_SerializesPerUser(t *testing.T) {
	cfg := defaultCfg()
	client := newFakeUserClient(t, map[string]map[string][]string{"grace": nil})
	m := New(client, cfg)

	const n = 50
	var wg sync.WaitGroup
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			_, err := m.Apply(context.Background(), "grace", &evaluator.Assessment{RiskLevel: evaluator.RiskLow})
			assert.NoError(t, err)
		}()
	}
	wg.Wait()

	traits := client.users["grace"].GetTraits()
	got, err := strconv.Atoi(traits[TraitScore][0])
	require.NoError(t, err)
	// Start is 0, each call adds DeltaLow=1, clamp at Max=20.
	assert.Equal(t, cfg.Max, got)
	assert.Equal(t, n, client.updates)
}

