// Package telemetry wires up an OTel meter provider. When OTLP is disabled
// (empty endpoint), a no-op provider is returned so record calls remain safe
// and cheap throughout the hot path.
package telemetry

import (
	"context"
	"fmt"

	"go.opentelemetry.io/otel/attribute"
	"go.opentelemetry.io/otel/exporters/otlp/otlpmetric/otlpmetricgrpc"
	"go.opentelemetry.io/otel/metric"
	"go.opentelemetry.io/otel/metric/noop"
	sdkmetric "go.opentelemetry.io/otel/sdk/metric"
	"go.opentelemetry.io/otel/sdk/resource"
)

const serviceName = "televibe"

// Instruments are the metric handles recorded on the evaluate path.
type Instruments struct {
	RiskScore       metric.Int64Histogram
	ReputationScore metric.Int64Gauge
	Adjustments     metric.Int64Counter
}

// Metrics owns the meter provider lifecycle plus the instruments. Shutdown
// flushes and releases the exporter; safe to call on a no-op provider.
type Metrics struct {
	Instruments Instruments
	Shutdown    func(context.Context) error
}

// New builds metric instruments. If endpoint is empty, a no-op meter is used
// and no OTLP connection is opened. Otherwise, OTLP gRPC metrics ship to
// endpoint (insecure; intended for an in-cluster collector on localhost:4317
// or similar).
func New(ctx context.Context, endpoint string) (*Metrics, error) {
	if endpoint == "" {
		instr, err := buildInstruments(noop.NewMeterProvider().Meter(serviceName))
		if err != nil {
			return nil, err
		}
		return &Metrics{
			Instruments: instr,
			Shutdown:    func(context.Context) error { return nil },
		}, nil
	}

	exp, err := otlpmetricgrpc.New(ctx,
		otlpmetricgrpc.WithEndpoint(endpoint),
		otlpmetricgrpc.WithInsecure(),
	)
	if err != nil {
		return nil, fmt.Errorf("otlp metric exporter: %w", err)
	}

	res, err := resource.New(ctx, resource.WithAttributes(
		attribute.String("service.name", serviceName),
	))
	if err != nil {
		return nil, fmt.Errorf("resource: %w", err)
	}

	provider := sdkmetric.NewMeterProvider(
		sdkmetric.WithReader(sdkmetric.NewPeriodicReader(exp)),
		sdkmetric.WithResource(res),
	)

	instr, err := buildInstruments(provider.Meter(serviceName))
	if err != nil {
		// Best-effort cleanup of the exporter if instrument setup fails.
		_ = provider.Shutdown(ctx)
		return nil, err
	}

	return &Metrics{
		Instruments: instr,
		Shutdown:    provider.Shutdown,
	}, nil
}

func buildInstruments(m metric.Meter) (Instruments, error) {
	riskScore, err := m.Int64Histogram(
		"televibe.assessment.risk_score",
		metric.WithDescription("Risk score assigned by the evaluator (1-10)"),
	)
	if err != nil {
		return Instruments{}, fmt.Errorf("risk_score histogram: %w", err)
	}

	repScore, err := m.Int64Gauge(
		"televibe.reputation.score",
		metric.WithDescription("Current reputation score for a user after the latest assessment"),
	)
	if err != nil {
		return Instruments{}, fmt.Errorf("reputation.score gauge: %w", err)
	}

	adjustments, err := m.Int64Counter(
		"televibe.reputation.adjustments",
		metric.WithDescription("Count of reputation adjustments applied, tagged by risk_level"),
	)
	if err != nil {
		return Instruments{}, fmt.Errorf("adjustments counter: %w", err)
	}

	return Instruments{
		RiskScore:       riskScore,
		ReputationScore: repScore,
		Adjustments:     adjustments,
	}, nil
}

