	if err != nil {
		logger.Error("configuration error", "error", err)
		os.Exit(1)
	}

	ctx, cancel := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer cancel()

	metrics, err := telemetry.New(ctx, cfg.OTLPEndpoint)
	if err != nil {
		logger.Error("telemetry init failed", "error", err)
		os.Exit(1)
	}
	defer func() {
		shutdownCtx, shutdownCancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer shutdownCancel()
		if err := metrics.Shutdown(shutdownCtx); err != nil {
			logger.Error("telemetry shutdown", "error", err)
		}
	}()
	if cfg.OTLPEndpoint == "" {
		logger.Info("OTLP metric shipping disabled (OTEL_EXPORTER_OTLP_ENDPOINT unset)")
	} else {
		logger.Info("OTLP metric shipping enabled", "endpoint", cfg.OTLPEndpoint)
	}

	var anthropicClient anthropic.Client
	switch cfg.LLMProvider {
	case config.ProviderBedrock:
		opts := []func(*awsconfig.LoadOptions) error{}
		if cfg.BedrockRegion != "" {
			opts = append(opts, awsconfig.WithRegion(cfg.BedrockRegion))
		}
		anthropicClient = anthropic.NewClient(bedrock.WithLoadDefaultConfig(context.Background(), opts...))
		logger.Info("using AWS Bedrock", "region", cfg.BedrockRegion, "model", cfg.ClaudeModel)
	default:
		anthropicClient = anthropic.NewClient(option.WithAPIKey(cfg.AnthropicAPIKey))
		logger.Info("using Anthropic API", "model", cfg.ClaudeModel)
	}

	eval := evaluator.New(anthropicClient, cfg.ClaudeModel)

	teleportClient, err := watcher.NewClient(ctx, cfg.TeleportAddr, cfg.TeleportIdentityFile)
	if err != nil {
		logger.Error("failed to connect to teleport", "error", err)
		os.Exit(1)
	}
	defer teleportClient.Close()

	reputationMgr := reputation.New(teleportClient, cfg.Reputation)

	w := watcher.New(ctx, teleportClient, logger)

	logger.Info("televibe started", "teleport_addr", cfg.TeleportAddr, "model", cfg.ClaudeModel)

	for {
		select {
		case req, ok := <-w.Requests():
			if !ok {
				return
			}
			go evaluate(ctx, eval, reputationMgr, metrics.Instruments, req, logger)
		case <-ctx.Done():
			return
		}
	}
}

func evaluate(
	ctx context.Context,
	eval *evaluator.Evaluator,
	rep *reputation.Manager,
	instr telemetry.Instruments,
	req evaluator.Request,
	logger *slog.Logger,
) {
	a, err := eval.Evaluate(ctx, req)
	if err != nil {
		logger.Error("evaluation failed", "request_id", req.ID, "user", req.User, "error", err)
		return
	}

	instr.RiskScore.Record(ctx, int64(a.RiskScore), metric.WithAttributes(
		attribute.String("risk_level", string(a.RiskLevel)),
		attribute.Bool("has_ticket", a.HasJIRATicket),
	))

	update, repErr := rep.Apply(ctx, req.User, a)
	if repErr != nil {
		logger.Error("reputation update failed",
			"request_id", req.ID,
			"user", req.User,
			"error", repErr,
		)
	} else {
		instr.ReputationScore.Record(ctx, int64(update.New), metric.WithAttributes(
			attribute.String("user", update.User),
		))
		instr.Adjustments.Add(ctx, 1, metric.WithAttributes(
			attribute.String("risk_level", string(a.RiskLevel)),
			attribute.String("direction", deltaDirection(update.Delta)),
		))
	}

	attrs := []any{
		"request_id", req.ID,
		"user", req.User,
		"roles", req.Roles,
		"risk_score", a.RiskScore,
		"risk_level", a.RiskLevel,
		"has_jira_ticket", a.HasJIRATicket,
		"jira_ticket", a.JIRATicket,
		"description_quality", a.DescriptionQuality,
		"reasoning", a.Reasoning,
	}
	if repErr == nil {
		attrs = append(attrs,
			"reputation_previous", update.Previous,
			"reputation_delta", update.Delta,
			"reputation_new", update.New,
		)
	}
	logger.Info("access request evaluated", attrs...)
	_ = strconv.Itoa // keep import stable if we later decide to format scores
}

func deltaDirection(d int) string {
	switch {
	case d > 0:
		return "positive"
	case d < 0:
		return "negative"
	default:
		return "zero"
	}
}
